/*  Example 12.1: Counting digits
    Author:  Peter Brusilovsky
    last updated;  3/21/01
*/
#include <stdio.h>
main () {
     int c, i, j;
     int ndigs[10];

     /* initialize */
     for(i = 0; i < 10; ++i) ndigs[i] = 0;

     /* count */
     while ((c = getchar()) != EOF)
          if (c >= '0' && c <= '9')
               ++ndigs[c - '0'];

     /* report */
     printf("\n   ^\n");
     for (i = 0; i < 10; ++i)   {
          printf(" %d |", i);
          for(j=1; j <= ndigs[i]; ++j)
                    printf("*");
          printf("\n");
     }
     printf("   +------------------>\n");
}
